WITH flattened AS (SELECT id, service, host, level, latency_ms, status_code, k, value FROM app_logs LATERAL VIEW EXPLODE(context) e AS k, value), flattened_attrs AS (SELECT id, service, status_code, k, CAST((status_code & 8) != 0 AS INT) AS flag_bit8, SHIFTRIGHT(status_code, 2) AS status_code_high FROM flattened WHERE status_code > 350), latest AS (SELECT *, RANK() OVER (PARTITION BY service ORDER BY flag_bit8 ASC) AS rank_in_group FROM flattened_attrs QUALIFY rank_in_group = 1) SELECT k, COUNT_IF(service = 'billing') AS billing_events, COUNT(CASE WHEN k = 'region' THEN 1 END) AS region_count, COUNT(CASE WHEN service = 'auth' THEN 1 END) AS auth_count, APPROX_PERCENTILE(flag_bit8, ARRAY(0.25, 0.5, 0.75)) AS flag_bit8_quartiles, ROUND(AVG(flag_bit8), 2) AS avg_flag_bit8, SUM(CASE WHEN k = 'region' THEN status_code_high ELSE 0 END) AS region_status_code_high FROM latest GROUP BY 1 ORDER BY region_status_code_high DESC;
